import{_ as o,a0 as t,w as u,s as x,I as a,x as n,a1 as p,A as l,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"使用 Fluxbox 桌面作為你的窗口管理器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Fluxbox 桌面作為你的窗口管理器 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Fluxbox 桌面作為你的窗口管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Fluxbox 桌面作為你的窗口管理器 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20191209 Use the Fluxbox Linux desktop as your window manager","title":"使用 Fluxbox 桌面作為你的窗口管理器","tag":"202004","desc":""},"relativePath":"202004/20191209 Use the Fluxbox Linux desktop as your window manager.md","filePath":"[post].md"}'),r={name:"202004/20191209 Use the Fluxbox Linux desktop as your window manager.md"};function d(b,s,f,c,m,g){const e=t("Link");return u(),x("div",null,[s[26]||(s[26]=a("h1",{id:"使用-fluxbox-桌面作為你的窗口管理器",tabindex:"-1"},[n("使用 Fluxbox 桌面作為你的窗口管理器 "),a("a",{class:"header-anchor",href:"#使用-fluxbox-桌面作為你的窗口管理器","aria-label":"Permalink to “使用 Fluxbox 桌面作為你的窗口管理器”"},"​")],-1)),s[27]||(s[27]=a("blockquote",null,[a("p",null,"本文是 24 天 Linux 桌面特別系列的一部分。Fluxbox 對系統資源的佔用非常輕量，但它擁有重要的 Linux 桌面功能，讓你的用户體驗輕鬆、高效、快捷。")],-1)),s[28]||(s[28]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202004/07/113105p0ng5skkn5kmvdm0.jpg",alt:""})],-1)),s[29]||(s[29]=a("p",null,"桌面的概念可謂是仁者見仁智者見智。很多人把桌面看作一個家的基地，或者一個舒適的客廳，甚至是一個字面意義上的桌面，在其中放置着他們經常使用的記事本、最好的筆和鉛筆，還有他們最喜歡的咖啡杯。KDE、 GNOME、Pantheon 等等在 Linux 上提供了這種舒適的生活方式。",-1)),a("p",null,[s[1]||(s[1]=n("但是對一些用户來説，桌面只是一個空蕩蕩的顯示器空間，這是還沒有任何可以自由浮動的應用程序窗口直接投射到他們的視網膜上的副作用。對於這些用户來説，桌面是一個空的空間，他們可以在上面運行應用程序 —— 無論是大型辦公軟件和圖形套件，還是一個簡單的終端窗口，或是來管理服務的托盤小程序。這種操作 ",-1)),p(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:l(()=>[...s[0]||(s[0]=[n("POSIX",-1)])]),_:1}),s[2]||(s[2]=n(" 計算機的模式由來已久，該家族樹的一支是 *box 窗口管理器：Blackbox、Fluxbox 和 Openbox。",-1))]),a("p",null,[p(e,{href:"http://fluxbox.org"},{default:l(()=>[...s[3]||(s[3]=[n("Fluxbox",-1)])]),_:1}),s[4]||(s[4]=n(" 是一個 X11 系統的窗口管理器，它基於一個較老的名為 Blackbox 的項目。當我發現 Linux 時，Blackbox 的開發已進入衰退期，因此我就喜歡上了 Fluxbox ，此後我至少在一個以上的常用的系統上使用過它。它是用 C++ 編寫的，並在 MIT 開源許可證下授權。",-1))]),s[30]||(s[30]=a("h3",{id:"安裝-fluxbox",tabindex:"-1"},[n("安裝 Fluxbox "),a("a",{class:"header-anchor",href:"#安裝-fluxbox","aria-label":"Permalink to “安裝 Fluxbox”"},"​")],-1)),a("p",null,[s[6]||(s[6]=n("你很可能會在你的 Linux 發行版的軟件庫中找到 Fluxbox，但是你也可以在 ",-1)),p(e,{href:"http://fluxbox.org/download/"},{default:l(()=>[...s[5]||(s[5]=[n("Fluxbox.org",-1)])]),_:1}),s[7]||(s[7]=n(" 上找到它。如果你正在運行另外一個桌面，在同一個系統上安裝 Fluxbox 是安全的，因為 Fluxbox 不會預設任何配置或附帶的應用程序。",-1))]),s[31]||(s[31]=i('<p>在安裝 Fluxbox 後，註銷你當前的桌面會話，以便你可以登錄一個新的桌面會話。默認情況下，你的桌面會話管理器 (KDM、GDM、LightDM 或 XDM，取決於你的安裝設置) 將繼續讓登錄到之前的桌面，所以你在登錄前必需要覆蓋上一個桌面。</p><p>使用 GDM 覆蓋一個桌面：</p><p><img src="https://opensource.com/sites/default/files/advent-gdm_0.jpg" alt="在 GDM 中選擇你的桌面會話" title="Select your desktop session in GDM"></p><p>或者使用 KDM：</p><p><img src="https://opensource.com/sites/default/files/advent-kdm.jpg" alt="使用 KDM 選擇你的桌面會話" title="Select your desktop session with KDM"></p><h3 id="配置-fluxbox-桌面" tabindex="-1">配置 Fluxbox 桌面 <a class="header-anchor" href="#配置-fluxbox-桌面" aria-label="Permalink to “配置 Fluxbox 桌面”">​</a></h3><p>當你第一次登錄到桌面時，屏幕基本是空的，因為 Fluxbox 提供的所有東西是面板（用於任務欄、系統托盤等等）和用於應用程序窗口的窗口裝飾品。</p><p><img src="https://opensource.com/sites/default/files/advent-fluxbox-default.jpg" alt="在 CentOS 7 上的默認 Fluxbox 配置" title="Default Fluxbox configuration on CentOS 7"></p><p>如果你的發行版提供一個簡單的 Fluxbox 桌面，你可以使用 <code>feh</code> 命令（你可能需要從你的發行版的軟件庫中安裝它）來為你的桌面設置背景。這個命令有幾個用於設置背景的選項，包括使用你選擇的牆紙來填充屏幕的 <code>--bg-fill</code> 選項，來按比例縮放的 <code>--bg-scale</code> 等等選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ feh --bg-fill ~/photo/oamaru/leaf-spiral.jpg</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/advent-fluxbox-green.jpg" alt="應用主題的 Fluxbox " title="Fluxbox with a theme applied"></p><p>默認情況下，Fluxbox 自動生成一個菜單，在桌面上任意位置右鍵單擊可用該菜單，這給予你訪問應用程序的能力。根據你的發行版的不同，這個菜單可能非常小，也可能列出 <code>/usr/share/applications</code> 目錄中的所有啓動程序。</p><p>Fluxbox 配置是在文本文件中設置的，這些文本文件包含在 <code>$HOME/.fluxbox</code> 目錄中。你可以：</p><ul><li>在 <code>keys</code> 中設置鍵盤快捷鍵</li><li>在 <code>startup</code> 中啓動的服務和應用程序</li><li>在 <code>init</code> 設置桌面首選項（例如工作區數量、面板位置等等）</li><li>在 <code>menu</code> 中設置菜單項</li></ul>',14)),a("p",null,[s[9]||(s[9]=n("該文本配置文件非常易於推斷，但是你也可以（並且是應該）閲讀 Fluxbox 的",-1)),p(e,{href:"http://fluxbox.org/features/"},{default:l(()=>[...s[8]||(s[8]=[n("文檔",-1)])]),_:1}),s[10]||(s[10]=n("。",-1))]),s[32]||(s[32]=i(`<p>例如，這是我的典型菜單（或者説至少有它的基本結構）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 為使用你自己的菜單，複製這些文本到 ~/.fluxbox/menu，然後編輯</span></span>
<span class="line"><span># ~/.fluxbox/init ，並更改 session.menuFile 文件路徑到 ~/.fluxbox/menu</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[begin] (fluxkbox)</span></span>
<span class="line"><span> [submenu] (apps) {}</span></span>
<span class="line"><span>  [submenu] (txt) {}</span></span>
<span class="line"><span>   [exec] (Emacs 23 (text\\)) { x-terminal-emulator -T &quot;Emacs (text)&quot; -e /usr/bin/emacs -nw} &lt;&gt;</span></span>
<span class="line"><span>   [exec] (Emacs (X11\\)) {/usr/bin/emacs} &lt;&gt;</span></span>
<span class="line"><span>   [exec] (LibreOffice) {/usr/bin/libreoffice}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (code) {}</span></span>
<span class="line"><span>   [exec] (qtCreator) {/usr/bin/qtcreator}</span></span>
<span class="line"><span>   [exec] (eclipse) {/usr/bin/eclipse}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (graphics) {}</span></span>
<span class="line"><span>   [exec] (ksnapshot) {/usr/bin/ksnapshot}</span></span>
<span class="line"><span>   [exec] (gimp) {/usr/bin/gimp}</span></span>
<span class="line"><span>   [exec] (blender) {/usr/bin/blender}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (files) {}</span></span>
<span class="line"><span>   [exec] (dolphin) {/usr/bin/dolphin}</span></span>
<span class="line"><span>   [exec] (konqueror) { /usr/bin/kfmclient openURL $HOME }</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (network) {}</span></span>
<span class="line"><span>   [exec] (firefox) {/usr/bin/firefox}</span></span>
<span class="line"><span>   [exec] (konqueror) {/usr/bin/konqueror}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span> [end]</span></span>
<span class="line"><span>## 更改窗口管理器或工作環境</span></span>
<span class="line"><span>[submenu] (environments) {}</span></span>
<span class="line"><span> [restart] (flux)  {/usr/bin/startfluxbox}</span></span>
<span class="line"><span> [restart] (ratpoison)  {/usr/bin/ratpoison}</span></span>
<span class="line"><span> [exec] (openIndiana) {/home/kenlon/qemu/startSolaris.sh}</span></span>
<span class="line"><span>[end]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[config] (config)</span></span>
<span class="line"><span> [submenu] (styles) {}</span></span>
<span class="line"><span>  [stylesdir] (/usr/share/fluxbox/styles)</span></span>
<span class="line"><span>  [stylesdir] (~/.fluxbox/styles)</span></span>
<span class="line"><span> [end]</span></span>
<span class="line"><span>[workspaces] (workspaces)</span></span>
<span class="line"><span>[reconfig] (reconfigure)</span></span>
<span class="line"><span>[restart] (restart)</span></span>
<span class="line"><span>[exit] (exeunt)</span></span>
<span class="line"><span>[end]</span></span></code></pre></div><p>該菜單也提供一些首選項設置，例如，選擇一個主題，從 Fluxbox 會話中重啓或註銷的能力。</p><p>我使用鍵盤快捷鍵來啓動大多數的應用程序，這些快捷鍵寫入到 <code>keys</code> 配置文件中。這裏有一些示例（<code>Mod4</code> 按鍵是 <code>Super</code> 鍵，我使用其來指定全局快捷鍵）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 打開應用程序</span></span>
<span class="line"><span>Mod4 t :Exec konsole</span></span>
<span class="line"><span>Mod4 k :Exec konqueror</span></span>
<span class="line"><span>Mod4 z :Exec fbrun</span></span>
<span class="line"><span>Mod4 e :Exec emacs</span></span>
<span class="line"><span>Mod4 f :Exec firefox</span></span>
<span class="line"><span>Mod4 x :Exec urxvt</span></span>
<span class="line"><span>Mod4 d :Exec dolphin</span></span>
<span class="line"><span>Mod4 q :Exec xscreensaver-command -activate</span></span>
<span class="line"><span>Mod4 3 :Exec ksnapshot</span></span></code></pre></div><p>在這些快捷方式和一個打開的終端之間，在我工作日的大部分時間內很少使用鼠標，因此從一個控制器切換到另一個控制器不會浪費時間。並且因為 Fluxbox 很好地避開了控制器之間切換的方法，因此在其中操作沒有一絲干擾。</p><h3 id="為什麼你應該使用-fluxbox" tabindex="-1">為什麼你應該使用 Fluxbox <a class="header-anchor" href="#為什麼你應該使用-fluxbox" aria-label="Permalink to “為什麼你應該使用 Fluxbox”">​</a></h3><p>Fluxbox 對系統資源的佔用非常輕量，但是它擁有重要的功能，可以使你的用户體驗輕鬆、快速、高效。它很容易定製，並且允許你定義你自己的工作流。你不必使用 Fluxbox 的面板，因為還有其它優秀的面板。你甚至可以鼠標中鍵點擊並拖動兩個獨立的應用程序窗口到彼此之中，以便它們成為一個窗口，每個窗口都有自己的選項卡。</p><p>可能性是無窮的，所以今天就在你的 Linux 上嘗試一下 Fluxbox 的簡單穩定吧！</p><hr>`,10)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/19/12/fluxbox-linux-desktop"},{default:l(()=>[...s[11]||(s[11]=[n("https://opensource.com/article/19/12/fluxbox-linux-desktop",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[13]||(s[13]=[n("Seth Kenlon",-1)])]),_:1}),s[18]||(s[18]=n(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[14]||(s[14]=[n("lujun9972",-1)])]),_:1}),s[19]||(s[19]=n(" 譯者：",-1)),p(e,{href:"https://github.com/robsean"},{default:l(()=>[...s[15]||(s[15]=[n("robsean",-1)])]),_:1}),s[20]||(s[20]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:l(()=>[...s[22]||(s[22]=[n("Linux中國",-1)])]),_:1}),s[25]||(s[25]=n(" 榮譽推出",-1))])])}const T=o(r,[["render",d]]);export{F as __pageData,T as default};
